 90	    private Node insert(Node current, int data, InsertionState state) {
 91	        if (current == null) {
 92	            return new Node(data, RedBlackTreeColor.RED);
 93	        }
 94	
 95	        Side insertionSide = insertionSide(current, data);
 96	        Node insertedChild = insert(current.child(insertionSide), data, state);
 97	        current.setChild(insertionSide, insertedChild);
 98	        insertedChild.parent = current;
 99	        boolean redRedConflict = hasRedRedConflict(current, insertionSide);
100	
101	        current = applyPendingRotation(current, state);
102	
103	        if (redRedConflict) {
104	            resolveRedRedConflict(current, state);
105	        }
106	
107	        return current;
