110	    private Node applyPendingRotation(Node current, InsertionState state) {
111	        switch (state.pendingRotation) {
112	            case LEFT_LEFT:
113	                current = rotateLeft(current);
114	                recolorAfterSingleRotation(current, Side.LEFT);
115	                break;
116	            case RIGHT_RIGHT:
117	                current = rotateRight(current);
118	                recolorAfterSingleRotation(current, Side.RIGHT);
119	                break;
120	            case RIGHT_LEFT:
121	                current = rotateChildThenCurrent(current, Side.RIGHT, Rotation.RIGHT_RIGHT);
122	                current = rotateLeft(current);
123	                recolorAfterSingleRotation(current, Side.LEFT);
124	                break;
125	            case LEFT_RIGHT:
126	                current = rotateChildThenCurrent(current, Side.LEFT, Rotation.LEFT_LEFT);
127	                current = rotateRight(current);
128	                recolorAfterSingleRotation(current, Side.RIGHT);
129	                break;
130	            case NONE:
131	                break;
132	        }
133	
134	        state.pendingRotation = Rotation.NONE;
