138	    private void resolveRedRedConflict(Node current, InsertionState state) {
139	        Node parent = current.parent;
140	        Side side = sideOf(parent, current);
141	        Node uncle = siblingChild(parent, side);
142	
143	        if (isBlack(uncle)) {
144	            state.pendingRotation = chooseRotation(current, side);
145	        } else {
