155	    private void recolorForRedUncle(Node current, Node uncle) {
156	        uncle.color = RedBlackTreeColor.BLACK;
157	        current.color = RedBlackTreeColor.BLACK;
158	        if (current.parent != root) {
159	            current.parent.color = RedBlackTreeColor.RED;
160	        }
161	    }
