163	    private Rotation chooseRotation(Node current, Side side) {
164	        if (side == Side.RIGHT) {
165	            if (isRed(current.child(Side.LEFT))) {
166	                return Rotation.RIGHT_LEFT;
167	            }
168	            if (isRed(current.child(Side.RIGHT))) {
169	                return Rotation.LEFT_LEFT;
170	            }
171	        } else {
172	            if (isRed(current.child(Side.LEFT))) {
173	                return Rotation.RIGHT_RIGHT;
174	            }
175	            if (isRed(current.child(Side.RIGHT))) {
176	                return Rotation.LEFT_RIGHT;
177	            }
178	        }
179	
180	        return Rotation.NONE;
181	    }
