183	    private Node rotateLeft(Node node) {
184	        Node pivot = node.right;
185	        Node transferredSubtree = pivot.left;
186	
187	        pivot.left = node;
188	        pivot.parent = node.parent;
189	        node.parent = pivot;
190	        node.right = transferredSubtree;
191	
192	        if (transferredSubtree != null) {
193	            transferredSubtree.parent = node;
194	        }
195	
196	        return pivot;
197	    }
