199	    private Node rotateRight(Node node) {
200	        Node pivot = node.left;
201	        Node transferredSubtree = pivot.right;
202	
203	        pivot.right = node;
204	        pivot.parent = node.parent;
205	        node.parent = pivot;
206	        node.left = transferredSubtree;
207	
208	        if (transferredSubtree != null) {
209	            transferredSubtree.parent = node;
210	        }
211	
212	        return pivot;
213	    }
