223	    private Side insertionSide(Node current, int data) {
224	        return data < current.data ? Side.LEFT : Side.RIGHT;
225	    }
226	
227	    private boolean hasRedRedConflict(Node current, Side childSide) {
228	        return current != root && isRed(current) && isRed(current.child(childSide));
229	    }
230	
231	    private Side sideOf(Node parent, Node child) {
232	        return parent.right == child ? Side.RIGHT : Side.LEFT;
233	    }
234	
235	    private Node siblingChild(Node parent, Side side) {
236	        return side == Side.RIGHT ? parent.left : parent.right;
237	    }
