239	    private Node rotateChildThenCurrent(Node current, Side childSide, Rotation childRotation) {
240	        Node rotatedChild = childRotation == Rotation.RIGHT_RIGHT
241	            ? rotateRight(current.child(childSide))
242	            : rotateLeft(current.child(childSide));
243	        current.setChild(childSide, rotatedChild);
244	        rotatedChild.parent = current;
245	        return current;
246	    }
