  4	final class RedBlackTreeSnapshot {
  5	    private static final int PRINT_INDENT = 10;
  6	
  7	    record NodeSnapshot(
  8	        int data,
  9	        RedBlackTreeColor color,
 10	        NodeSnapshot left,
 11	        NodeSnapshot right
 12	    ) {
 13	    }
 14	
 15	    private final NodeSnapshot root;
 16	
 17	    RedBlackTreeSnapshot(NodeSnapshot root) {
 18	        this.root = root;
 19	    }
 20	
 21	    NodeSnapshot root() {
 22	        return root;
 23	    }
 24	
 25	    List<Integer> inorderValues() {
 26	        List<Integer> values = new ArrayList<>();
 27	        collectInorder(root, values);
 28	        return values;
 29	    }
 30	
 31	    String inorderString() {
 32	        StringBuilder builder = new StringBuilder();
 33	        appendInorder(root, builder);
 34	        return builder.toString();
 35	    }
 36	
 37	    String formatTree() {
 38	        StringBuilder builder = new StringBuilder();
 39	        appendTree(root, 0, builder);
 40	        return builder.toString();
 41	    }
 42	
 43	    boolean isValid() {
 44	        if (root == null) {
 45	            return true;
 46	        }
 47	
 48	        if (root.color() != RedBlackTreeColor.BLACK) {
 49	            return false;
 50	        }
 51	
 52	        return isBinarySearchTree(root, Long.MIN_VALUE, Long.MAX_VALUE)
 53	            && hasNoRedRedViolation(root)
 54	            && blackHeight(root) != -1;
 55	    }
 56	
 57	    private void collectInorder(NodeSnapshot node, List<Integer> values) {
 58	        if (node == null) {
 59	            return;
 60	        }
 61	
 62	        collectInorder(node.left(), values);
 63	        values.add(node.data());
 64	        collectInorder(node.right(), values);
 65	    }
 66	
 67	    private void appendInorder(NodeSnapshot node, StringBuilder builder) {
 68	        if (node == null) {
 69	            return;
 70	        }
 71	
 72	        appendInorder(node.left(), builder);
 73	        if (builder.length() > 0) {
 74	            builder.append(' ');
 75	        }
 76	        builder.append(node.data());
 77	        appendInorder(node.right(), builder);
 78	    }
 79	
 80	    private void appendTree(NodeSnapshot node, int space, StringBuilder builder) {
 81	        if (node == null) {
 82	            return;
 83	        }
 84	
 85	        int nextSpace = space + PRINT_INDENT;
 86	        appendTree(node.right(), nextSpace, builder);
 87	        builder.append('\n');
 88	        for (int i = PRINT_INDENT; i < nextSpace; i++) {
 89	            builder.append(' ');
 90	        }
 91	        builder.append(node.data()).append('\n');
 92	        appendTree(node.left(), nextSpace, builder);
 93	    }
 94	
 95	    private boolean isBinarySearchTree(NodeSnapshot node, long minInclusive, long maxExclusive) {
 96	        if (node == null) {
 97	            return true;
 98	        }
 99	
100	        if (node.data() < minInclusive || node.data() >= maxExclusive) {
101	            return false;
102	        }
103	
104	        return isBinarySearchTree(node.left(), minInclusive, node.data())
105	            && isBinarySearchTree(node.right(), node.data(), maxExclusive);
106	    }
107	
108	    private boolean hasNoRedRedViolation(NodeSnapshot node) {
109	        if (node == null) {
110	            return true;
111	        }
112	
113	        if (isRed(node) && (isRed(node.left()) || isRed(node.right()))) {
114	            return false;
115	        }
116	
117	        return hasNoRedRedViolation(node.left()) && hasNoRedRedViolation(node.right());
118	    }
119	
120	    private int blackHeight(NodeSnapshot node) {
121	        if (node == null) {
122	            return 1;
123	        }
124	
125	        int leftHeight = blackHeight(node.left());
126	        int rightHeight = blackHeight(node.right());
127	        if (leftHeight == -1 || rightHeight == -1 || leftHeight != rightHeight) {
128	            return -1;
129	        }
130	
131	        return leftHeight + (node.color() == RedBlackTreeColor.BLACK ? 1 : 0);
132	    }
133	
134	    private boolean isRed(NodeSnapshot node) {
135	        return node != null && node.color() == RedBlackTreeColor.RED;
136	    }
137	}

